const data = $input.first().json;
const message = data.body.message;
const chat = data.body.chat;

const phone = (message.chatid || '').split('@')[0];
const isGroup = message.chatid?.includes('@g.us') || false;
const name = message.senderName || 'Paciente';
const isAudio = message.messageType === 'AudioMessage';
const msg = message.text || '';
const messageid = message.messageid || '';
const token = data.body.token || '';

// Dados do áudio
const mediaUrl = message.content?.URL || '';
const mediaKey = message.content?.mediaKey || '';
const mimetype = message.content?.mimetype || '';
const fileSHA256 = message.content?.fileSHA256 || '';
const fileLength = message.content?.fileLength || 0;

let transcription = '';

// Se for áudio, já transcreve aqui mesmo
if (isAudio && messageid) {
  try {
    const response = await fetch('https://YOUR_INSTANCE.uazapi.com/message/download', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'token': token
      },
      body: JSON.stringify({
        id: messageid,
        transcribe: true,
        generate_mp3: true,
        openai_apikey: "YOUR_OPENAI_API_KEY_HERE"
      })
    });
    const result = await response.json();
    transcription = result.transcription || '';
  } catch(e) {
    transcription = '';
  }
}

return [{ json: { 
  chatInput: isAudio ? transcription : msg,
  text: isAudio ? transcription : msg,
  phone, 
  name, 
  isGroup,
  isAudio,
  mediaUrl,
  mediaKey,
  mimetype,
  fileSHA256,
  fileLength,
  token,
  messageid,
  transcription
}}];
